create or replace function sovereign_private.pair(a text,b text) returns text language sql immutable as $$select case when a<b then a||'_'||b else b||'_'||a end$$;
create or replace function sovereign_private.name(a text) returns text language sql stable as $$select c->>'name' from sovereign_private.seed,jsonb_array_elements(world->'countries') c where id=1 and c->>'id'=a$$;
create or replace function sovereign_private.meta(a text) returns jsonb language sql stable as $$select p from sovereign_private.seed,jsonb_array_elements(world->'provinces') p where id=1 and p->>'id'=a$$;
create or replace function sovereign_private.def(kind text,item text) returns jsonb language sql immutable as $$select case when kind='build' then
 jsonb_build_object('industry','{"name":"Complexe industriel","seconds":40,"cost":{"credits":800,"industry":60}}'::jsonb,'farm','{"name":"Réseau agricole","seconds":30,"cost":{"credits":550,"industry":35}}'::jsonb,'energy','{"name":"Centre énergétique","seconds":40,"cost":{"credits":750,"industry":50}}'::jsonb,'fort','{"name":"Base fortifiée","seconds":35,"cost":{"credits":650,"industry":70}}'::jsonb,'hospital','{"name":"Services publics","seconds":45,"cost":{"credits":900,"industry":50}}'::jsonb,'market','{"name":"Pôle commercial","seconds":50,"cost":{"credits":1000,"industry":75}}'::jsonb)->item
 else jsonb_build_object('infantry','{"name":"Infanterie","seconds":18,"power":40,"speed":1,"cost":{"credits":420,"supply":40,"industry":25},"upkeep":9}'::jsonb,'armor','{"name":"Brigade blindée","seconds":32,"power":85,"speed":0.8,"cost":{"credits":950,"fuel":65,"industry":75},"upkeep":22}'::jsonb,'air','{"name":"Escadron aérien","seconds":40,"power":65,"speed":2.5,"cost":{"credits":1200,"fuel":90,"industry":95},"upkeep":28}'::jsonb)->item end$$;
create or replace function sovereign_private.log(s jsonb,typ text,title text,body text,author text default 'Agence européenne') returns jsonb language plpgsql as $$begin
 s=jsonb_set(s,'{news}',jsonb_build_array(jsonb_build_object('id',(s->>'next')::int,'at',(s->>'clock')::numeric,'type',typ,'title',title,'body',body,'author',author))||(s->'news'));
 s=jsonb_set(s,'{next}',to_jsonb((s->>'next')::int+1));
 s=jsonb_set(s,'{news}',coalesce((select jsonb_agg(v order by n) from jsonb_array_elements(s->'news') with ordinality a(v,n) where n<=100),'[]'::jsonb));return s;end$$;
create or replace function sovereign_private.pay(s jsonb,country text,cost jsonb) returns jsonb language plpgsql as $$declare k text;v numeric;begin
 for k,v in select key,value::numeric from jsonb_each_text(cost) loop if coalesce((s#>>array['countries',country,k])::numeric,0)<v then raise exception 'Ressources insuffisantes.';end if;end loop;
 for k,v in select key,value::numeric from jsonb_each_text(cost) loop s=jsonb_set(s,array['countries',country,k],to_jsonb((s#>>array['countries',country,k])::numeric-v));end loop;return s;end$$;
create or replace function sovereign_private.power(u jsonb) returns numeric language sql immutable as $$select (sovereign_private.def('recruit',u->>'type')->>'power')::numeric*(u->>'hp')::numeric/100$$;
create or replace function sovereign_private.route(s jsonb,country text,src text,dst text) returns jsonb language plpgsql as $$declare queue jsonb:=jsonb_build_array(jsonb_build_array(src));route jsonb;last text;nxt text;seen text[]:=array[src];owner text;begin
 if sovereign_private.meta(src) is null or sovereign_private.meta(dst) is null then return null;end if;
 while jsonb_array_length(queue)>0 loop route=queue->0;queue=queue-0;last=route->>-1;if last=dst then return route;end if;
 for nxt in select jsonb_array_elements_text(sovereign_private.meta(last)->'neighbors') loop
 if nxt=any(seen) then continue;end if;owner=s#>>array['provinces',nxt,'owner'];
 if nxt<>dst and owner<>country and coalesce(s#>>array['relations',sovereign_private.pair(country,owner),'status'],'peace')<>'alliance' then continue;end if;
 seen=array_append(seen,nxt);queue=queue||jsonb_build_array(route||to_jsonb(nxt));end loop;end loop;return null;end$$;
create or replace function sovereign_private.income(s jsonb,country text) returns jsonb language plpgsql as $$declare out jsonb:='{"credits":0,"industry":0,"fuel":0,"supply":0}';p jsonb;b jsonb;c jsonb:=s#>array['countries',country];u jsonb;r jsonb;count_p int:=0;budget numeric:=0;industry numeric:=0;fuel numeric:=0;supply numeric:=0;begin
 for p in select value from jsonb_each(s->'provinces') where value->>'owner'=country loop count_p=count_p+1;b=p->'buildings';budget=budget+coalesce((b->>'market')::numeric,0)*130-coalesce((b->>'hospital')::numeric,0)*35;industry=industry+coalesce((b->>'industry')::numeric,0)*24;fuel=fuel+coalesce((b->>'energy')::numeric,0)*28;supply=supply+coalesce((b->>'farm')::numeric,0)*35;end loop;
 budget=budget+count_p*(75+(c->>'tax')::numeric*2.8);industry=industry+count_p*7;fuel=fuel+count_p*6;supply=supply+count_p*12;
 for u in select value from jsonb_array_elements(s->'units') where value->>'owner'=country loop budget=budget-(sovereign_private.def('recruit',u->>'type')->>'upkeep')::numeric;supply=supply-case when u->>'type'='infantry' then 6 else 4 end;fuel=fuel-case u->>'type' when 'armor' then 5 when 'air' then 9 else 0 end;end loop;
 for r in select value from jsonb_each(s->'relations') where country=any(string_to_array(key,'_')) loop if (r->>'trade')::boolean and r->>'status'<>'war' then budget=budget+90;industry=industry+8;end if;end loop;
 if c->>'policy'='social' then budget=budget-120;end if;if c->>'policy'='industrial' then budget=budget-90;industry=industry+20;end if;if (c->>'approval')::numeric<30 then budget=budget*.7;end if;
 return jsonb_build_object('credits',budget,'industry',industry,'fuel',fuel,'supply',supply);end$$;
create or replace function sovereign_private.respond(s jsonb,t jsonb,accept boolean) returns jsonb language plpgsql as $$declare k text:=sovereign_private.pair(t->>'from',t->>'to');r jsonb:=s#>array['relations',k];begin
 s=jsonb_set(s,'{proposals}',coalesce((select jsonb_agg(v) from jsonb_array_elements(s->'proposals') v where v->>'id'<>t->>'id'),'[]'::jsonb));
 if not accept then return sovereign_private.log(s,'diplomacy','Proposition refusée',sovereign_private.name(t->>'to')||' refuse la proposition de '||sovereign_private.name(t->>'from')||'.');end if;
 if t->>'kind'<>'peace' and r->>'status'='war' then return sovereign_private.log(s,'diplomacy','Proposition caduque','Le conflit empêche la signature.');end if;
 if t->>'kind'='trade' then r=jsonb_set(r,'{trade}','true');end if;if t->>'kind'='alliance' then r=jsonb_set(r,'{status}','"alliance"');end if;
 if t->>'kind'='peace' then r=jsonb_set(r,'{status}','"peace"');r=jsonb_set(r,'{truce}',to_jsonb((s->>'clock')::numeric+90));r=jsonb_set(r,'{value}','30');end if;
 s=jsonb_set(s,array['relations',k],r);return sovereign_private.log(s,'diplomacy','Accord signé',sovereign_private.name(t->>'from')||' et '||sovereign_private.name(t->>'to')||' signent un accord de '||(t->>'kind')||'.');end$$;
create or replace function sovereign_private.advance(s jsonb,seconds numeric) returns jsonb language plpgsql as $$declare end_at numeric:=(s->>'clock')::numeric+greatest(0,least(seconds,86400));delta numeric;event numeric;clock numeric;k text;c jsonb;inc jsonb;hospitals numeric;q jsonb;remaining jsonb;u jsonb;d jsonb;m jsonb;p jsonb;owner text;status text;def numeric;atk numeric;fort numeric;fresh jsonb;idx int;proposal jsonb;cnt int;begin
 while (s->>'clock')::numeric<end_at and s->>'victor' is null loop
 clock=(s->>'clock')::numeric;
 select min(v) into event from (select (x->>'due')::numeric v from jsonb_array_elements(s->'queue') x union all select (x#>>'{moving,due}')::numeric from jsonb_array_elements(s->'units') x where x->'moving'<>'null'::jsonb union all select (x->>'due')::numeric from jsonb_array_elements(s->'proposals') x where x->'due'<>'null'::jsonb) ev;
 delta=least(end_at-clock,greatest(.001,coalesce(event,end_at)-clock));
 for k,c in select key,value from jsonb_each(s->'countries') loop inc=sovereign_private.income(s,k);
 c=jsonb_set(c,'{credits}',to_jsonb(greatest(0,(c->>'credits')::numeric+(inc->>'credits')::numeric*delta/60)));
 c=jsonb_set(c,'{industry}',to_jsonb(greatest(0,(c->>'industry')::numeric+(inc->>'industry')::numeric*delta/60)));
 c=jsonb_set(c,'{fuel}',to_jsonb(greatest(0,(c->>'fuel')::numeric+(inc->>'fuel')::numeric*delta/60)));
 c=jsonb_set(c,'{supply}',to_jsonb(greatest(0,(c->>'supply')::numeric+(inc->>'supply')::numeric*delta/60)));
 select coalesce(sum(coalesce((value#>>'{buildings,hospital}')::numeric,0)),0) into hospitals from jsonb_each(s->'provinces') where value->>'owner'=k;
 c=jsonb_set(c,'{approval}',to_jsonb(greatest(0,least(100,(c->>'approval')::numeric+((20-(c->>'tax')::numeric)*.07+case when c->>'policy'='social' then 1.2 else 0 end+hospitals*.8-case when (c->>'supply')::numeric=0 then 4 else 0 end-case when (c->>'credits')::numeric=0 then 3 else 0 end)*delta/60))));s=jsonb_set(s,array['countries',k],c);end loop;
 clock=clock+delta;s=jsonb_set(s,'{clock}',to_jsonb(clock));remaining='[]';
 for q in select value from jsonb_array_elements(s->'queue') loop if (q->>'due')::numeric>clock then remaining=remaining||jsonb_build_array(q);continue;end if;
 if s#>>array['provinces',q->>'province','owner']<>q->>'country' then s=sovereign_private.log(s,'war','Préparation perdue','Le secteur a été occupé.');continue;end if;
 if q->>'type'='build' then s=jsonb_set(s,array['provinces',q->>'province','buildings',q->>'item'],to_jsonb(coalesce((s#>>array['provinces',q->>'province','buildings',q->>'item'])::int,0)+1));else
 s=jsonb_set(s,'{units}',(s->'units')||jsonb_build_array(jsonb_build_object('id','u'||(s->>'next'),'owner',q->>'country','type',q->>'item','province',q->>'province','hp',100,'moving',null,'name',sovereign_private.def('recruit',q->>'item')->>'name')));s=jsonb_set(s,'{next}',to_jsonb((s->>'next')::int+1));end if;
 s=sovereign_private.log(s,case when q->>'type'='build' then 'economy' else 'army' end,'Préparation terminée',(sovereign_private.def(q->>'type',q->>'item')->>'name')||' à '||(sovereign_private.meta(q->>'province')->>'name')||'.');end loop;s=jsonb_set(s,'{queue}',remaining);
 for u in select value from jsonb_array_elements(s->'units') where value->'moving'<>'null'::jsonb and (value#>>'{moving,due}')::numeric<=clock loop
 if not exists(select 1 from jsonb_array_elements(s->'units') v where v->>'id'=u->>'id') then continue;end if;
 m=u->'moving';p=s#>array['provinces',m->>'target'];owner=p->>'owner';status=case when owner=u->>'owner' then 'self' else s#>>array['relations',sovereign_private.pair(u->>'owner',owner),'status'] end;u=jsonb_set(u,'{moving}','null');
 if status in ('self','alliance') then u=jsonb_set(u,'{province}',m->'target');elsif status='war' then
 fort=1+coalesce((p#>>'{buildings,fort}')::numeric,0)*.25+case when sovereign_private.meta(m->>'target')->>'terrain'='mountain' then .2 else 0 end;
 select coalesce(sum(sovereign_private.power(v)),0)*fort into def from jsonb_array_elements(s->'units') v where v->>'owner'=owner and v->>'province'=m->>'target' and v->'moving'='null'::jsonb;
 atk=sovereign_private.power(u)*case when (s#>>array['countries',u->>'owner','supply'])::numeric>0 then 1 else .65 end*case when u->>'type'='air' then 1.1 else 1 end;
 if atk>=def then
 s=jsonb_set(s,'{units}',coalesce((select jsonb_agg(v) from jsonb_array_elements(s->'units') v where not(v->>'owner'=owner and v->>'province'=m->>'target' and v->'moving'='null'::jsonb)),'[]'::jsonb));
 s=jsonb_set(s,array['provinces',m->>'target','owner'],u->'owner');u=jsonb_set(u,'{province}',m->'target');u=jsonb_set(u,'{hp}',to_jsonb(greatest(15,(u->>'hp')::numeric-least(70,def/greatest(1,atk)*70))));s=sovereign_private.log(s,'army',(sovereign_private.meta(m->>'target')->>'name')||' sécurisé','Le secteur passe sous contrôle de '||sovereign_private.name(u->>'owner')||'.');
 else
 fresh='[]';for d in select value from jsonb_array_elements(s->'units') loop if d->>'id'=u->>'id' then continue;end if;if d->>'owner'=owner and d->>'province'=m->>'target' and d->'moving'='null'::jsonb then d=jsonb_set(d,'{hp}',to_jsonb(greatest(10,(d->>'hp')::numeric-atk/greatest(1,def)*45)));end if;fresh=fresh||jsonb_build_array(d);end loop;s=jsonb_set(s,'{units}',fresh);s=sovereign_private.log(s,'war','Offensive repoussée','Une force engagée à '||(sovereign_private.meta(m->>'target')->>'name')||' a été détruite.');continue;
 end if;
 else s=sovereign_private.log(s,'army','Opération suspendue','La diplomatie interdit l’entrée sur ce territoire.');end if;
 select (n-1)::int into idx from jsonb_array_elements(s->'units') with ordinality a(v,n) where v->>'id'=u->>'id';if idx is not null then s=jsonb_set(s,array['units',idx::text],u);end if;
 end loop;
 for proposal in select value from jsonb_array_elements(s->'proposals') where value->'due'<>'null'::jsonb and (value->>'due')::numeric<=clock loop
 s=sovereign_private.respond(s,proposal,(proposal->>'kind'='peace') or (s#>>array['relations',sovereign_private.pair(proposal->>'from',proposal->>'to'),'value'])::numeric>=case when proposal->>'kind'='alliance' then 70 else 45 end);end loop;
 for k in select key from jsonb_each(s->'countries') loop select count(*) into cnt from jsonb_each(s->'provinces') where value->>'owner'=k;if cnt>=40 then s=jsonb_set(s,'{victor}',to_jsonb(k));s=sovereign_private.log(s,'world','Nouvel équilibre continental',sovereign_private.name(k)||' contrôle la majorité stratégique.');exit;end if;end loop;
 end loop;return s;end$$;
create or replace function sovereign_private.apply(s jsonb,country text,a jsonb) returns jsonb language plpgsql as $$declare typ text:=a->>'type';c jsonb:=s#>array['countries',country];p jsonb:=s#>array['provinces',a->>'province'];b jsonb;count_q int;q jsonb;k text;refund_value numeric;u jsonb;idx int;dest jsonb;r jsonb;route jsonb;secs numeric:=0;pos int;one jsonb;two jsonb;dl numeric;dy numeric;item text:=a->>'item';target text:=a->>'target';proposal jsonb;title text;body text;cost jsonb;amount int;res text;price numeric;begin
 if c is null then raise exception 'Pays inconnu.';end if;if s->>'victor' is not null then raise exception 'Partie terminée.';end if;
 if not exists(select 1 from jsonb_each(s->'provinces') where value->>'owner'=country) then raise exception 'Votre gouvernement a perdu tous ses territoires.';end if;
 if typ='recruit' and jsonb_array_length(s->'units')+(select count(*) from jsonb_array_elements(s->'queue') z where z->>'type'='recruit')>=800 then raise exception 'La limite de 800 unités du salon est atteinte.';end if;
 if typ in ('build','recruit') then b=sovereign_private.def(typ,item);if p is null or p->>'owner'<>country or b is null then raise exception 'Secteur ou équipement invalide.';end if;
 select count(*) into count_q from jsonb_array_elements(s->'queue') v where v->>'country'=country and v->>'province'=a->>'province';if count_q>=3 then raise exception 'Trois préparations sont déjà en cours ici.';end if;
 if typ='build' then select count(*) into count_q from jsonb_array_elements(s->'queue') v where v->>'type'='build' and v->>'province'=a->>'province' and v->>'item'=item;if coalesce((p#>>array['buildings',item])::int,0)+count_q>=3 then raise exception 'Niveau maximum : 3.';end if;end if;
 s=sovereign_private.pay(s,country,b->'cost');s=jsonb_set(s,'{queue}',(s->'queue')||jsonb_build_array(jsonb_build_object('id','q'||(s->>'next'),'country',country,'province',a->>'province','type',typ,'item',item,'due',(s->>'clock')::numeric+(b->>'seconds')::numeric)));s=jsonb_set(s,'{next}',to_jsonb((s->>'next')::int+1));return s;end if;
 if typ='cancel' then select value into q from jsonb_array_elements(s->'queue') where value->>'id'=a->>'id' and value->>'country'=country;if q is null then raise exception 'Ordre introuvable.';end if;
 for k,refund_value in select key,value::numeric from jsonb_each_text(sovereign_private.def(q->>'type',q->>'item')->'cost') loop s=jsonb_set(s,array['countries',country,k],to_jsonb((s#>>array['countries',country,k])::numeric+refund_value*.75));end loop;s=jsonb_set(s,'{queue}',coalesce((select jsonb_agg(v) from jsonb_array_elements(s->'queue') v where v->>'id'<>a->>'id'),'[]'::jsonb));return s;end if;
 if typ='move' then select v,(n-1)::int into u,idx from jsonb_array_elements(s->'units') with ordinality t(v,n) where v->>'id'=a->>'unit' and v->>'owner'=country;
 dest=s#>array['provinces',target];if u is null or u->'moving'<>'null'::jsonb or dest is null or u->>'province'=target then raise exception 'Unité indisponible.';end if;
 if dest->>'owner'<>country then r=s#>array['relations',sovereign_private.pair(country,dest->>'owner')];if r->>'status' not in ('alliance','war') then raise exception 'Déclarez la guerre ou négociez une alliance.';end if;end if;
 route=sovereign_private.route(s,country,u->>'province',target);if route is null then raise exception 'Aucune route accessible.';end if;
 for pos in 1..jsonb_array_length(route)-1 loop one=sovereign_private.meta(route->>(pos-1))->'geo';two=sovereign_private.meta(route->>pos)->'geo';dl=((one->>0)::numeric-(two->>0)::numeric)*cos(((one->>1)::numeric+(two->>1)::numeric)*pi()/360);dy=(one->>1)::numeric-(two->>1)::numeric;secs=secs+sqrt(dl*dl+dy*dy)*111;end loop;
 secs=greatest(6,least(85,secs/13/(sovereign_private.def('recruit',u->>'type')->>'speed')::numeric));s=sovereign_private.pay(s,country,jsonb_build_object('fuel',ceil(secs*.7)));
 u=jsonb_set(u,'{moving}',jsonb_build_object('from',u->>'province','target',target,'route',route,'start',(s->>'clock')::numeric,'due',(s->>'clock')::numeric+secs));return jsonb_set(s,array['units',idx::text],u);end if;
 if typ='tax' then if (a->>'value')::numeric<>trunc((a->>'value')::numeric) or (a->>'value')::int not between 10 and 35 then raise exception 'Impôts invalides.';end if;return jsonb_set(s,array['countries',country,'tax'],a->'value');end if;
 if typ='policy' then if a->>'value' not in ('balanced','social','industrial') then raise exception 'Politique invalide.';end if;return jsonb_set(s,array['countries',country,'policy'],a->'value');end if;
 if typ='trade-resource' then res=a->>'resource';amount=(a->>'amount')::int;if res not in ('fuel','industry','supply') or amount not in (25,50,100) then raise exception 'Transaction invalide.';end if;price=case res when 'fuel' then 5 when 'industry' then 6 else 3 end;
 if (a->>'buy')::boolean then s=sovereign_private.pay(s,country,jsonb_build_object('credits',price*amount));s=jsonb_set(s,array['countries',country,res],to_jsonb((s#>>array['countries',country,res])::numeric+amount));else s=sovereign_private.pay(s,country,jsonb_build_object(res,amount));s=jsonb_set(s,array['countries',country,'credits'],to_jsonb((s#>>array['countries',country,'credits'])::numeric+floor(price*amount*.7)));end if;return s;end if;
 if typ='diplomacy' then k=sovereign_private.pair(country,target);r=s#>array['relations',k];if r is null or target=country then raise exception 'Pays invalide.';end if;
 if a->>'kind'='war' then if r->>'status'='war' then raise exception 'Déjà en guerre.';end if;if (r->>'truce')::numeric>(s->>'clock')::numeric then raise exception 'Une trêve est active.';end if;
 r=r||'{"status":"war","trade":false,"value":-75}'::jsonb;s=jsonb_set(s,array['relations',k],r);s=jsonb_set(s,array['countries',country,'approval'],to_jsonb(greatest(0,(c->>'approval')::numeric-6)));return sovereign_private.log(s,'war',sovereign_private.name(country)||' déclare la guerre à '||sovereign_private.name(target),'Les frontières passent en alerte.',c->>'leader');end if;
 if a->>'kind'='delegation' then if r->>'status'='war' then raise exception 'Négociez la paix.';end if;s=sovereign_private.pay(s,country,'{"credits":300}');r=jsonb_set(r,'{value}',to_jsonb(least(100,(r->>'value')::numeric+15)));s=jsonb_set(s,array['relations',k],r);return sovereign_private.log(s,'diplomacy','Visite diplomatique',sovereign_private.name(country)||' envoie une délégation en '||sovereign_private.name(target)||'.',c->>'leader');end if;
 if a->>'kind' not in ('trade','alliance','peace') then raise exception 'Accord invalide.';end if;
 if a->>'kind'='peace' and r->>'status'<>'war' then raise exception 'Aucun conflit.';end if;if a->>'kind'<>'peace' and r->>'status'='war' then raise exception 'La paix est nécessaire.';end if;
 if a->>'kind'='trade' and (r->>'trade')::boolean then raise exception 'Commerce déjà actif.';end if;if a->>'kind'='alliance' and r->>'status'='alliance' then raise exception 'Déjà alliés.';end if;
 if exists(select 1 from jsonb_array_elements(s->'proposals') v where v->>'from'=country and v->>'to'=target and v->>'kind'=a->>'kind') then raise exception 'Proposition déjà en attente.';end if;
 proposal=jsonb_build_object('id','t'||(s->>'next'),'from',country,'to',target,'kind',a->>'kind','at',(s->>'clock')::numeric,'due',case when s#>>array['members',target] is null then (s->>'clock')::numeric+8 else null end);
 s=jsonb_set(s,'{proposals}',(s->'proposals')||jsonb_build_array(proposal));s=jsonb_set(s,'{next}',to_jsonb((s->>'next')::int+1));return sovereign_private.log(s,'diplomacy','Proposition diplomatique',sovereign_private.name(country)||' propose un accord à '||sovereign_private.name(target)||'.',c->>'leader');end if;
 if typ='respond' then select value into proposal from jsonb_array_elements(s->'proposals') where value->>'id'=a->>'id' and value->>'to'=country;if proposal is null then raise exception 'Proposition introuvable.';end if;return sovereign_private.respond(s,proposal,(a->>'accept')::boolean);end if;
 if typ='publish' then title=left(btrim(a->>'title'),90);body=left(btrim(a->>'body'),1200);if coalesce(title,'')='' or coalesce(body,'')='' then raise exception 'Texte incomplet.';end if;
 if exists(select 1 from jsonb_array_elements(s->'news') v where v->>'type'='statement' and v->>'author'=c->>'leader' and (s->>'clock')::numeric-(v->>'at')::numeric<5) then raise exception 'Attendez 5 secondes.';end if;return sovereign_private.log(s,'statement',title,body,c->>'leader');end if;
 if typ='message' then body=left(btrim(a->>'body'),500);if coalesce(body,'')='' then raise exception 'Message vide.';end if;if target is not null and (target=country or s#>array['countries',target] is null) then raise exception 'Destinataire invalide.';end if;
 if exists(select 1 from jsonb_array_elements(coalesce(s->'messages','[]')) v where v->>'from'=country and (s->>'clock')::numeric-(v->>'at')::numeric<1) then raise exception 'Attendez une seconde.';end if;
 s=jsonb_set(s,'{messages}',coalesce(s->'messages','[]')||jsonb_build_array(jsonb_build_object('id',(s->>'next')::int,'from',country,'to',target,'body',body,'at',(s->>'clock')::numeric)));s=jsonb_set(s,'{next}',to_jsonb((s->>'next')::int+1));s=jsonb_set(s,'{messages}',coalesce((select jsonb_agg(v order by n) from jsonb_array_elements(s->'messages') with ordinality t(v,n) where n>jsonb_array_length(s->'messages')-150),'[]'::jsonb));return s;end if;
 raise exception 'Ordre inconnu.';end$$;
create or replace function sovereign_private.view(s jsonb,country text,code text) returns jsonb language plpgsql as $$begin
 s=jsonb_set(s,'{messages}',coalesce((select jsonb_agg(v) from jsonb_array_elements(coalesce(s->'messages','[]')) v where v->>'to' is null or v->>'from'=country or v->>'to'=country),'[]'::jsonb));
 return jsonb_build_object('code',code,'state',s,'country',country,'serverTime',extract(epoch from now()),'members',(select coalesce(jsonb_agg(jsonb_build_object('country',m.country,'leader',m.leader,'online',m.seen_at>now()-interval '15 seconds')),'[]'::jsonb) from public.sovereign_members m where m.room=code));end$$;
create or replace function public.sovereign_create(p_country text,p_leader text,p_title text default 'Europe • Partie privée') returns jsonb language plpgsql security definer set search_path='' as $$declare code text;state jsonb;begin
 if auth.uid() is null then raise exception 'Connexion nécessaire.';end if;
 if (select count(*) from public.sovereign_rooms where host=auth.uid())>=3 then raise exception 'Trois salons maximum. Réutilisez un code existant.';end if;
 select s.state into state from sovereign_private.seed s where id=1;if state#>array['countries',p_country] is null then raise exception 'Pays invalide.';end if;
 if length(btrim(p_leader)) not between 1 and 40 then raise exception 'Nom de dirigeant invalide.';end if;
 code=upper(left(replace(gen_random_uuid()::text,'-',''),8));state=jsonb_set(state,array['countries',p_country,'leader'],to_jsonb(btrim(p_leader)));state=jsonb_set(state,'{members}',jsonb_build_object(p_country,btrim(p_leader)));
 insert into public.sovereign_rooms(code,host,title,state) values(code,auth.uid(),left(coalesce(p_title,'Europe'),60),state);
 insert into public.sovereign_members(room,user_id,country,leader) values(code,auth.uid(),p_country,btrim(p_leader));return sovereign_private.view(state,p_country,code);end$$;
create or replace function public.sovereign_join(p_code text,p_country text,p_leader text) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.sovereign_rooms%rowtype;m public.sovereign_members%rowtype;new_state jsonb;begin
 if auth.uid() is null then raise exception 'Connexion nécessaire.';end if;
 select * into r from public.sovereign_rooms where code=upper(btrim(p_code)) for update;if not found then raise exception 'Code de salon introuvable.';end if;
 select * into m from public.sovereign_members where room=r.code and user_id=auth.uid();if found then return sovereign_private.view(r.state,m.country,r.code);end if;
 if r.state#>array['countries',p_country] is null then raise exception 'Pays invalide.';end if;
 if length(btrim(p_leader)) not between 1 and 40 then raise exception 'Nom invalide.';end if;
 if exists(select 1 from public.sovereign_members where room=r.code and country=p_country) then raise exception 'Ce pays est déjà joué. Choisissez une autre nation.';end if;
 if not exists(select 1 from jsonb_each(r.state->'provinces') where value->>'owner'=p_country) then raise exception 'Ce pays a été éliminé.';end if;
 insert into public.sovereign_members(room,user_id,country,leader) values(r.code,auth.uid(),p_country,btrim(p_leader));new_state=sovereign_private.advance(r.state,extract(epoch from now()-r.last_step));new_state=jsonb_set(new_state,array['countries',p_country,'leader'],to_jsonb(btrim(p_leader)));new_state=jsonb_set(new_state,array['members',p_country],to_jsonb(btrim(p_leader)));
 update public.sovereign_rooms set state=new_state,last_step=now() where code=r.code;return sovereign_private.view(new_state,p_country,r.code);end$$;
create or replace function public.sovereign_sync(p_code text,p_action jsonb default null) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.sovereign_rooms%rowtype;m public.sovereign_members%rowtype;s jsonb;begin
 if auth.uid() is null then raise exception 'Connexion nécessaire.';end if;
 select * into m from public.sovereign_members where room=upper(btrim(p_code)) and user_id=auth.uid();if not found then raise exception 'Vous ne participez pas à ce salon.';end if;
 select * into r from public.sovereign_rooms where code=m.room for update;s=sovereign_private.advance(r.state,extract(epoch from now()-r.last_step));
 if p_action is not null then if octet_length(p_action::text)>8000 then raise exception 'Ordre trop volumineux.';end if;s=sovereign_private.apply(s,m.country,p_action);end if;
 update public.sovereign_rooms set state=s,last_step=now() where code=m.room;update public.sovereign_members set seen_at=now() where room=m.room and user_id=auth.uid();return sovereign_private.view(s,m.country,m.room);end$$;
revoke execute on all functions in schema sovereign_private from public,anon,authenticated;
revoke execute on function public.sovereign_create(text,text,text),public.sovereign_join(text,text,text),public.sovereign_sync(text,jsonb) from public,anon;
grant execute on function public.sovereign_create(text,text,text),public.sovereign_join(text,text,text),public.sovereign_sync(text,jsonb) to authenticated;
commit;
